// Dashboard.js
import { useLocation, useNavigate } from "react-router-dom";
import { useEffect } from "react";

function Dashboard() {
    const location = useLocation();
    const navigate = useNavigate();

    // Try to access full API response safely
    const fullData = location.state?.data;
    const responseData = fullData?.Response;

    useEffect(() => {
        // If not coming from Login (user refresh or direct visit)
        if (!responseData) {
            navigate("/login");
        }
    }, [responseData, navigate]);

    if (!responseData) {
        return <p>Redirecting to login...</p>;
    }

    return (
        <div className="container">
            <h1>Dashboard</h1>

            <div style={{ 
                backgroundColor: "#f9f9f9", 
                padding: "20px", 
                borderRadius: "8px", 
                boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
                marginTop: "1rem"
            }}>
                <h3>Status: {responseData.Status}</h3>
                <h3>Message: {responseData.Message}</h3>

                {responseData.UserInfo && (
                    <div>
                        <h4>User Info</h4>
                        <pre style={{ whiteSpace: "pre-wrap" }}>
                            {JSON.stringify(responseData.UserInfo, null, 2)}
                        </pre>
                    </div>
                )}
            </div>
        </div>
    );
}

export default Dashboard;
